def chain_follow(WELL_FORMED):
    chain = []
    current_char = WELL_FORMED[0][0]
    for pair in WELL_FORMED[1:]:
        next_char = pair[0]
        if next_char == current_char:
            chain.append(pair[1])
        else:
            chain.append(pair[1])
            current_char = next_char
    chain.append(WELL_FORMED[-1][1])
    return ','.join(chain)
